  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single batch be split across multiple vats (with its total processing time being the sum of the parts), or must each batch be assigned whole to exactly one vat?"
  ],
  "rationale": "The response asks for a single policy choice regarding batch assignment, presenting two mutually exclusive options."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When a batch moves from one vat to the next, does it have to wait for the next vat to be completely free, or can it start in the next vat as soon as that vat finishes its current batch (i.e., is this a standard flow shop where each vat processes one batch at a time)?"
  ],
  "rationale": "The response asks a single clarification question regarding the scheduling logic for batch transitions between vats."
}

